"""Independent validation of a UC schedule, reading only input data + arrays."""
import numpy as np


def interp_cost(pts, q):
    if q <= pts[0][0]:
        return pts[0][1]
    if q >= pts[-1][0]:
        return pts[-1][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x0 <= q <= x1:
            return y0 + (q - x0) * (y1 - y0) / (x1 - x0)
    raise ValueError("outside curve")


def choose_startup_cost(tiers, dur):
    tiers = sorted(tiers, key=lambda z: z["lag"])
    chosen = tiers[0]
    for tier in tiers:
        if tier["lag"] <= dur:
            chosen = tier
        else:
            break
    return chosen["cost"]


def validate(case, u, v, w, p, r, pr, tol=1e-4):
    """u,v,w: (G,T) ints; p,r: (G,T); pr: (Rn,T). Returns (failures, cost)."""
    T, G, Rn = case["T"], case["G"], case["Rn"]
    D, Rq = case["D"], case["Rq"]
    thermal, gnames, rnames = case["thermal"], case["gnames"], case["rnames"]
    ren_min, ren_max = case["ren_min"], case["ren_max"]
    fails = []

    def chk(cond, msg):
        if not cond:
            fails.append(msg)

    chk(u.shape == (G, T) and v.shape == (G, T) and w.shape == (G, T)
        and p.shape == (G, T) and r.shape == (G, T), "array shapes")
    chk(pr.shape == (Rn, T), "renewable shape")
    chk(set(gnames) == set(thermal.keys()), "thermal names")
    chk(all(np.all(np.isin(x, (0, 1))) for x in (u, v, w)), "binary values")

    total_cost = 0.0
    startups = shutdowns = 0
    for gi, name in enumerate(gnames):
        g = thermal[name]
        prev_on, prev_p = g["u0"], g["p0"]
        off_dur = g["tdn0"] if not g["u0"] else 0
        on_dur = g["tup0"] if g["u0"] else 0
        for t in range(T):
            st = int(u[gi, t] == 1 and prev_on == 0)
            sp = int(u[gi, t] == 0 and prev_on == 1)
            chk(v[gi, t] == st, f"{name} start mismatch t{t}")
            chk(w[gi, t] == sp, f"{name} stop mismatch t{t}")
            chk(not (v[gi, t] and w[gi, t]), f"{name} simultaneous t{t}")
            if st:
                startups += 1
                # startup cost from prior offline duration
                total_cost += choose_startup_cost(g["tiers"], off_dur)
                off_dur = 0
                on_dur = 1
            elif sp:
                shutdowns += 1
                on_dur = 0
                off_dur = 1
            elif prev_on and u[gi, t]:
                on_dur += 1
            elif not prev_on and not u[gi, t]:
                off_dur += 1
            # offline zeroes
            if u[gi, t] == 0:
                chk(abs(p[gi, t]) <= tol, f"{name} nonzero p offline t{t}")
                chk(abs(r[gi, t]) <= tol, f"{name} nonzero r offline t{t}")
            else:
                chk(p[gi, t] >= g["pmin"] - tol, f"{name} below pmin t{t}")
                chk(p[gi, t] <= g["pmax"] + tol, f"{name} above pmax t{t}")
                # joint reserve capacity
                chk(p[gi, t] + r[gi, t] <= g["pmax"] + tol, f"{name} p+r>pmax t{t}")
                chk(r[gi, t] >= -tol, f"{name} negative reserve t{t}")
                chk(r[gi, t] <= g["RU"] + tol, f"{name} r>RU t{t}")
                if st:
                    chk(p[gi, t] + r[gi, t] <= g["PSu"] + tol, f"{name} startup cap t{t}")
                if sp and t > 0:
                    chk(p[gi, t - 1] + r[gi, t - 1] <= g["PSd"] + tol,
                        f"{name} preshutdown cap t{t}")
            # ramping (applies to production + reserve)
            prev_pr = prev_p + (r[gi, t - 1] if t > 0 else 0.0)
            if t == 0:
                if u[gi, t] == 1 and prev_on == 1:
                    chk(p[gi, t] + r[gi, t] - prev_p <= g["RU"] + tol, f"{name} rampup t0")
                chk(prev_p - p[gi, t] <= g["RD"] + tol or sp, f"{name} rampdown t0")
                if sp:
                    chk(prev_p <= g["PSd"] + tol, f"{name} shutdown ramp t0")
                if st:
                    chk(p[gi, t] + r[gi, t] <= g["PSu"] + tol, f"{name} startup ramp t0")
            else:
                if u[gi, t] == 1 and u[gi, t - 1] == 1:
                    chk(p[gi, t] + r[gi, t] - p[gi, t - 1] <= g["RU"] + tol,
                        f"{name} rampup t{t}")
                    chk(p[gi, t - 1] - p[gi, t] <= g["RD"] + tol, f"{name} rampdown t{t}")
                elif st:
                    chk(p[gi, t] + r[gi, t] <= g["PSu"] + tol, f"{name} startup ramp t{t}")
                elif sp:
                    chk(p[gi, t - 1] + r[gi, t - 1] <= g["PSd"] + tol,
                        f"{name} shutdown ramp t{t}")
            # min up/down windows (truncated at horizon)
            if st:
                for tau in range(t, min(T, t + g["UT"])):
                    chk(u[gi, tau] == 1, f"{name} minup t{t} tau{tau}")
            if sp:
                for tau in range(t, min(T, t + g["DT"])):
                    chk(u[gi, tau] == 0, f"{name} mindown t{t} tau{tau}")
            # production cost
            if u[gi, t] == 1:
                total_cost += interp_cost(g["pts"], p[gi, t])
            prev_on = int(u[gi, t])
            prev_p = p[gi, t]

    # must-run
    for gi, name in enumerate(gnames):
        if thermal[name]["must"]:
            chk(np.all(u[gi] == 1), f"{name} must-run offline")

    # balance / reserve / renewables
    bal = np.abs(p.sum(0) + pr.sum(0) - D)
    chk(bal.max() <= 1e-3, f"balance max viol {bal.max():.6f}")
    short = np.maximum(0.0, Rq - r.sum(0))
    chk(short.max() <= 1e-3, f"reserve shortfall {short.max():.6f}")
    for j, name in enumerate(rnames):
        chk(np.all(pr[j] >= ren_min[j] - tol), f"{name} ren below min")
        chk(np.all(pr[j] <= ren_max[j] + tol), f"{name} ren above max")

    return fails, dict(cost=total_cost, startups=startups, shutdowns=shutdowns,
                       max_bal=float(bal.max()), max_short=float(short.max()))

